let SlidersArray = []
function sliderProjectCard() {
    $(".project-card__slider").each(function(index, el) {
        $(el).attr("data-slider-id", `${index}`)
        SlidersArray[index] = new Swiper(`.project-card__slider[data-slider-id="${index}"] .swiper`, {
            slidesPerView: 1,
            spaceBetween: 10,
            effect: "fade",
            navigation: {
                nextEl: `.project-card__slider[data-slider-id="${index}"] .swiper-button-next`,
                prevEl: `.project-card__slider[data-slider-id="${index}"] .swiper-button-prev`,
            },
            pagination: {
                el: `.project-card__slider[data-slider-id="${index}"] .swiper-pagination`,
                clickable: true,
            },
        })
    })
}

function sliderCertificates() {
    var swiper = new Swiper('.certificates .mySwiper', {
        slidesPerView: 4,
        spaceBetween: 24,
        loop: false,
        navigation: {
            nextEl: ".certificates .swiper-button-next",
            prevEl: ".certificates .swiper-button-prev",
        },
        breakpoints: {
            320: {
                slidesPerView: 1,
                spaceBetween: 15,
                loop: true,
            },
            577: {
                slidesPerView: 2,
                spaceBetween: 15,
                loop: false,
            },
            769: {
                slidesPerView: 3,
                spaceBetween: 15,
                loop: false,
            },
            993: {
                slidesPerView: 4,
                spaceBetween: 24,
                loop: false,
            }
        }
    })
}

function sliderTeam() {
    var swiper = new Swiper('.team .mySwiper', {
        slidesPerView: 4,
        spaceBetween: 24,
        centeredSlides: false,
        loop: false,
        navigation: {
            nextEl: ".team .swiper-button-next",
            prevEl: ".team .swiper-button-prev",
        },
        effect: window.innerWidth < 577 ? 'coverflow' : 'slide',
        coverflowEffect: {
            rotate: 0,
            stretch: 0,
            depth: 50,
            modifier: 1.5,
            slideShadows: false,
        },
        Slides: window.innerWidth < 577,
        breakpoints: {
            320: {
                slidesPerView: 'auto',
                spaceBetween: 20,
                centeredSlides: true,
                loop: true,
            },
            577: {
                slidesPerView: 2,
                spaceBetween: 15,
                centeredSlides: false,
                loop: false,
            },
            769: {
                slidesPerView: 3,
                spaceBetween: 15,
                centeredSlides: false,
                loop: false,
            },
            993: {
                slidesPerView: 4,
                spaceBetween: 24,
                centeredSlides: false,
                loop: false,
            }
        },
        on: {
            init: function() {
                updateEffect(this);
            }
        }
    });

    function updateEffect(swiperInstance) {
        const isMobile = window.innerWidth < 577;

        if (isMobile) {
            swiperInstance.params.effect = 'coverflow';
            swiperInstance.params.centeredSlides = true;
            swiperInstance.params.slidesPerView = 'auto';
        } else {
            swiperInstance.params.effect = 'slide';
            swiperInstance.params.centeredSlides = false;
        }

        swiperInstance.update();
    }

    let resizeTimeout;
    window.addEventListener('resize', function() {
        clearTimeout(resizeTimeout);
        resizeTimeout = setTimeout(function() {
            updateEffect(swiper);
        }, 250);
    });
}

function sliderFeedback() {
    var swiper = new Swiper('.feedback .mySwiper', {
        slidesPerView: 2,
        spaceBetween: 24,
        grid: {
            rows: 1,
        },
        navigation: {
            nextEl: ".feedback .swiper-button-next",
            prevEl: ".feedback .swiper-button-prev",
        },
        breakpoints: {
            320: {
                slidesPerView: 1,
                spaceBetween: 15,
                grid: {
                    rows: 2,
                },
            },
            769: {
                slidesPerView: 2,
                spaceBetween: 15,
                grid: {
                    rows: 1,
                },
            },
            993: {
                slidesPerView: 2,
                spaceBetween: 24,
                grid: {
                    rows: 1,
                },
            },
        }
    })
}

$(document).ready(function () {
    sliderProjectCard();
    sliderCertificates();
    sliderTeam();
    sliderFeedback();

    // Header
    if (window.innerWidth >= 993) {
        $('.header__item').hover(function () {
            $(this).toggleClass('header__item--active')
        })
    }

    $('.burger').click(function () {
        $('.menu').addClass('menu--active')
        $('.menu-bg').addClass('menu-bg--active')
        $('body').addClass('fixed-body')
    })

    $('.menu-bg').click(function () {
        $('.menu').removeClass('menu--active')
        $(this).removeClass('menu-bg--active')
        $('body').removeClass('fixed-body')
    })

    $('.menu__close').click(function () {
        $('.menu').removeClass('menu--active')
        $('.menu-bg').removeClass('menu-bg--active')
        $('body').removeClass('fixed-body')
    })

    // Select
    $(".custom_select select").niceSelect()

    // Accordion
    $(".item-show").click((function(){
        $(this).parents('.item').toggleClass('item--active')
        $(this).toggleClass("item-show--active"),
        $(this).siblings(".item-hidden").slideToggle()
    }));

    // Tabs
    $(".tab").click(function () {
        let path = $(this).attr("data-tab-path")
        $(this).siblings(".tab").removeClass("tab--active")
        $(this).addClass("tab--active")

        $(this).parents(".tabs-inner").find(".tab__content").removeClass("tab__content--active")
        $(this).parents(".tabs-inner").find(`.tab__content[data-content-path="${path}"]`).addClass("tab__content--active")
    })

    // Up
    var t = $(".up");
    $(window).scroll(function() {
        $(window).scrollTop() > 300 ? t.addClass("up--active") : t.removeClass("up--active");
    });
    t.on("click", function(e) {
        e.preventDefault();
        $("html, body").animate({
            scrollTop: 0
        }, 300);
    });

    // Inputs
    $('.form-group input').each(function() {
        var $input = $(this);
        var $inputText = $input.siblings('.input-text');

        if ($input.val().trim() !== '') {
            $inputText.hide();
        }

        $input.on('input', function() {
            if ($(this).val().trim() !== '') {
                $inputText.hide();
            } else {
                $inputText.show();
            }
        });

        $input.on('blur', function() {
            if ($(this).val().trim() === '') {
                $input.show();
            }
        });
    });

    $('.phone-mask').inputmask("+7 (999) 999-99-99");

    // Cookie
    $('.cookie__close, .cookie__btn').click(function () {
        $(this).parents('.cookie').remove()
    })

    // Filter
    $('.filter__btn').click(function () {
        $('.sidebar').addClass('sidebar--active')
        $('.sidebar-bg').addClass('sidebar-bg--active')
        $('body').addClass('fixed-body')
    })

    $('.sidebar-bg').click(function () {
        $('.sidebar').removeClass('sidebar--active')
        $(this).removeClass('sidebar-bg--active')
        $('body').removeClass('fixed-body')
    })

    $('.sidebar__close').click(function () {
        $('.sidebar').removeClass('sidebar--active')
        $('.sidebar-bg').removeClass('sidebar-bg--active')
        $('body').removeClass('fixed-body')
    })

    // Modal
    $("[data-modal]").click(function () {
        let modalId = $(this).attr("data-modal")

        openModal(modalId)
    })

    function openModal(modalId){
        $(`#${modalId}`).addClass("modal--active")
        $("body").addClass("fixed-body")
    }

    $(".modal").click(function () {
        closeModal()
    })

    $("._close-modal").click(function () {
        closeModal()
    })

    $(".modal__dialog").click(function (e) {
        e.stopPropagation()
    })

    function closeModal() {
        $('.modal--active video').each(function () {
            this.pause();
            this.currentTime = 0;
        });

        $('.modal').removeClass("modal--active")
        $("body").removeClass("fixed-body")
    }


})

// RangeSlider
document.addEventListener('DOMContentLoaded', function() {
    function initSlider(sliderElement) {
        const min = parseFloat(sliderElement.dataset.min) || 0;
        const max = parseFloat(sliderElement.dataset.max) || 100;
        const start = sliderElement.dataset.start.split(',').map(Number);
        const step = parseFloat(sliderElement.dataset.step) || 1;

        const config = {
            start: start,
            connect: true,
            range: {
                'min': min,
                'max': max
            },
            step: step,
            format: {
                to: function(value) {
                    return Math.round(value * 100) / 100;
                },
                from: function(value) {
                    return Number(value);
                }
            }
        };

        noUiSlider.create(sliderElement, config);

        const rangeElement = sliderElement.closest('.range');
        const minInput = rangeElement.querySelector('[data-slider="min"]');
        const maxInput = rangeElement.querySelector('[data-slider="max"]');

        minInput.value = config.start[0];
        maxInput.value = config.start[1];

        sliderElement.noUiSlider.on('update', function(values, handle) {
            const formattedValue = config.format.to(values[handle]);
            if (handle === 0) {
                minInput.value = formattedValue;
            } else {
                maxInput.value = formattedValue;
            }
        });

        minInput.addEventListener('change', function() {
            const values = [this.value, null];
            sliderElement.noUiSlider.set(values);
        });

        maxInput.addEventListener('change', function() {
            const values = [null, this.value];
            sliderElement.noUiSlider.set(values);
        });
    }

    document.querySelectorAll('.range__slider').forEach(initSlider);
});